#include <LiquidCrystal.h>
LiquidCrystal lcd(12,11,5,4,3,2);
void setup(){ lcd.begin(16,2); lcd.print("Hola, ARDUNOVA!"); }
void loop(){ lcd.setCursor(0,1); lcd.print("Arduino en marcha"); delay(500); }

const int rojo=8, amarillo=9, verde=10;
void setup(){ pinMode(rojo,OUTPUT); pinMode(amarillo,OUTPUT); pinMode(verde,OUTPUT); }
void loop(){ digitalWrite(verde,HIGH); delay(4000); digitalWrite(verde,LOW); digitalWrite(amarillo,HIGH); delay(1500); digitalWrite(amarillo,LOW); digitalWrite(rojo,HIGH); delay(4000); digitalWrite(rojo,LOW); }

const int trigPin=9, echoPin=10;
void setup(){ pinMode(trigPin,OUTPUT); pinMode(echoPin,INPUT); Serial.begin(9600); }
void loop(){ digitalWrite(trigPin,LOW); delayMicroseconds(2); digitalWrite(trigPin,HIGH); delayMicroseconds(10); digitalWrite(trigPin,LOW); long t=pulseIn(echoPin,HIGH,30000); if(t==0) Serial.println("Sin lectura"); else { Serial.print(t*0.0343/2); Serial.println(" cm"); } delay(500); }

const int boton=2, led=13;
void setup(){ pinMode(boton,INPUT_PULLUP); pinMode(led,OUTPUT); }
void loop(){ digitalWrite(led, digitalRead(boton)==LOW ? HIGH : LOW); }

const int boton=2, led=13;
void setup(){ pinMode(boton,INPUT_PULLUP); pinMode(led,OUTPUT); }
void loop(){ int estado=digitalRead(boton); digitalWrite(led, estado==LOW ? HIGH : LOW); }

const int pot=A0, led=9;
void setup(){ pinMode(led,OUTPUT); }
void loop(){ int lectura=analogRead(pot); int brillo=map(lectura,0,1023,0,255); analogWrite(led,brillo); delay(10); }

const int sensor=A0, led=8;
const int umbral=600;
void setup(){ pinMode(led,OUTPUT); Serial.begin(9600); }
void loop(){ int humedad=analogRead(sensor); Serial.println(humedad); digitalWrite(led, humedad>umbral ? HIGH : LOW); delay(1000); }

const int sensorIzq=2, sensorDer=3;
